package com.styleshop.auth.controller;
import com.nimbusds.jose.jwk.*; import com.styleshop.auth.model.*; import com.styleshop.auth.repository.*; import com.styleshop.auth.service.JwtService; import jakarta.servlet.http.HttpSession; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.*; import java.util.concurrent.ThreadLocalRandom;
@RestController public class AuthController { private final UserRepository users; private final LoginLogRepository logs; private final PasswordEncoder passwords; private final JwtService jwt; private final RSAKey rsa;
 public AuthController(UserRepository u,LoginLogRepository l,PasswordEncoder p,JwtService j,RSAKey r){users=u;logs=l;passwords=p;jwt=j;rsa=r;}
 @GetMapping("/api/auth/captcha") public Map<String,String> captcha(HttpSession s){String c=String.valueOf(ThreadLocalRandom.current().nextInt(100000,1000000));s.setAttribute("captcha",c);return Map.of("captcha",c);}
 @PostMapping("/api/auth/login") public ResponseEntity<?> login(@RequestBody LoginRequest q,HttpSession s){String expected=(String)s.getAttribute("captcha");s.removeAttribute("captcha");if(expected==null||!expected.equals(q.captcha()))return ResponseEntity.badRequest().body(Map.of("message","驗證碼錯誤或已失效"));var user=users.findByUsername(q.username()).orElse(null);if(user==null||!passwords.matches(q.password(),user.getPassword())){log(q.username(),"FAIL","帳號或密碼錯誤");return ResponseEntity.status(401).body(Map.of("message","帳號或密碼錯誤"));}log(user.getUsername(),"SUCCESS","登入成功");return ResponseEntity.ok(Map.of("accessToken",jwt.create(user),"tokenType","Bearer","expiresIn",jwt.expires(),"username",user.getUsername(),"role",user.getRole(),"loggedIn",true));}
 @GetMapping("/api/auth/me") public Map<String,Object> me(Authentication a){String role=a.getAuthorities().stream().map(x->x.getAuthority().replace("ROLE_","")).findFirst().orElse("USER");return Map.of("loggedIn",true,"username",a.getName(),"role",role);}
 @PostMapping("/api/auth/logout") public Map<String,String> logout(){return Map.of("message","前端已移除 Access Token");}
 @GetMapping("/api/auth/.well-known/jwks.json") public Map<String,Object> jwks(){return new JWKSet(rsa.toPublicJWK()).toJSONObject();}
 @GetMapping("/internal/auth/login-logs") public List<LoginLog> loginLogs(){return logs.findTop500ByOrderByLoginTimeDesc();}
 private void log(String u,String s,String m){LoginLog l=new LoginLog();l.setUsername(u);l.setLoginTime(LocalDateTime.now());l.setStatus(s);l.setMessage(m);logs.save(l);} public record LoginRequest(String username,String password,String captcha){}
}
